class I18nManager:
    _instance = None
    current_lang = "en"

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(I18nManager, cls).__new__(cls)
            cls._instance.current_lang = "en"
        return cls._instance

    def _detect_system_language(self) -> str:
        try:
            for env_var in ("LC_ALL", "LC_MESSAGES", "LANG"):
                val = os.environ.get(env_var)
                if val:
                    lang_code = val.split(".")[0].split("_")[0].lower()
                    if lang_code in SUPPORTED_LANGUAGES:
                        return lang_code

            loc = locale.getlocale(locale.LC_MESSAGES)[0] or locale.getlocale()[0]
            if loc:
                lang_code = loc.split("_")[0].lower()
                if lang_code in SUPPORTED_LANGUAGES:
                    return lang_code
        except Exception as e:
            logger.debug("System language detection error: %s", e)
        return "en"

    def get_language(self) -> str:
        return getattr(self, "current_lang", "en")

    def set_language(self, lang_code: str):
        if lang_code == "auto":
            self.current_lang = self._detect_system_language()
        elif lang_code in SUPPORTED_LANGUAGES:
            self.current_lang = lang_code
        else:
            self.current_lang = "en"

    def get_text(self, _msg_key: str, lang: str | None = None, **kwargs) -> str:
        target_lang = lang or kwargs.pop("_lang", None) or kwargs.pop("lang", None) or self.current_lang
        lang_dict = TRANSLATIONS.get(target_lang, TRANSLATIONS.get("en", {}))
        text = lang_dict.get(_msg_key, TRANSLATIONS.get("en", {}).get(_msg_key, _msg_key))
        if kwargs:
            try:
                text = text.format(**kwargs)
            except (KeyError, IndexError, ValueError) as e:
                logger.debug("String format failed for key '%s': %s", _msg_key, e)
        return text

i18n = I18nManager()

def t(_msg_key: str, lang: str | None = None, **kwargs) -> str:
    return i18n.get_text(_msg_key, lang=lang, **kwargs)

def get_current_language() -> str:
    return i18n.get_language()

def get_month_name(month_num: int, short: bool = False, lang: str | None = None, genitive: bool = False) -> str:
    target_lang = lang or get_current_language()
    idx = max(0, min(11, month_num - 1))
    if genitive and target_lang in MONTHS_GENITIVE:
        gen_list = MONTHS_GENITIVE[target_lang]
        if 0 <= idx < len(gen_list):
            return gen_list[idx]
    store = MONTHS_SHORT if short else MONTHS_FULL
    lang_months = store.get(target_lang, store.get("en", []))
    if 0 <= idx < len(lang_months):
        return lang_months[idx]
    return ""


